 d=cat[cat.complex_id.eq(r.complex_id)].iloc[0];ys={str(int(v.year)):{'status':v.status,'median_manwon':None if pd.isna(v.median_manwon) else float(v.median_manwon),'n':int(v.n)} for v in by[r.complex_id].itertuples()};assert all(ys[str(y)]['status']=='not_yet_observed' for y in range(2006,int(d.first_valid_trade_year)));catalog.append({'complex_id':r.complex_id,'name':d['name'],'x_5179':r.x_5179,'y_5179':r.y_5179,'HSMP_INNB':r.HSMP_INNB,'PNU':r.PNU,'coord_quality':'official_2025_parcel_name_reviewed_native_point','first_valid_trade_year':int(d.first_valid_trade_year),'build_year':None if pd.isna(d.build_year) else int(d.build_year),'years':ys})
